const body = $input.first().json.body || {};
const errs = [];
if (!['creation','edition'].includes(body.mode)) errs.push('mode');
if (!['audio','texte'].includes(body.input_type)) errs.push('input_type');
if (body.input_type === 'texte' && !body.texte) errs.push('texte');
if (body.input_type === 'audio' && !body.audio_base64) errs.push('audio_base64');
if (!body.contexte || !body.contexte.entite_code) errs.push('contexte.entite_code');
if (!body.contexte || !body.contexte.client || !body.contexte.client.nom) errs.push('contexte.client');
if (body.mode === 'edition' && !(body.contexte && body.contexte.devis_courant && Array.isArray(body.contexte.devis_courant.lignes))) errs.push('contexte.devis_courant.lignes');
if (errs.length) return [{ json: { valid: false, champs: errs } }];
return [{ json: { valid: true, payload: body } }];

const p = $json.payload;
const buf = Buffer.from(p.audio_base64, 'base64');
if (!buf.length) return [{ json: { payload: p, audioVide: true } }];
const binary = await this.helpers.prepareBinaryData(buf, 'audio.webm', 'audio/webm');
return [{ json: { payload: p }, binary: { audio: binary } }];

const base = $('1. Validation payload').first().json.payload;
let consigne = null, transcription = null, sttError = null;
if (base.input_type === 'audio') {
  const r = $input.first().json || {};
  transcription = r.text || r.transcription || r.transcript || null;
  if (!transcription || !String(transcription).trim()) sttError = 'transcription_echouee';
  consigne = transcription;
} else {
  consigne = base.texte;
}
return [{ json: { payload: base, consigne, transcription, sttError } }];

const ctx = $('4. Consigne').first().json;
const p = ctx.payload;
const biblioItems = $input.all().map(i => i.json).filter(j => j && j.id && (j.libelle || j.designation));
const biblioTxt = biblioItems.length
  ? biblioItems.map(b => `${b.id} | ${b.code || ''} | ${b.libelle || b.designation} | ${b.unite || ''}`).join('\n')
  : '(bibliothèque vide — toutes les lignes seront libres, prestation_id null)';
const ENTITES = { PRO: 'ARTISAN PRO', EXT: 'EXTERIEUR', INT: 'INTERIEUR' };
const system = [
  `Tu es l'assistant de chiffrage d'une entreprise suisse de rénovation/construction (${ENTITES[p.contexte.entite_code] || p.contexte.entite_code}). Tu transformes une consigne (dictée ou tapée) en lignes de devis structurées. Règles absolues :`,
  `1. Tu ne calcules JAMAIS de montants, totaux ou TVA. Tu ne produis que la structure : désignations, unités, quantités.`,
  `2. Pour chaque prestation, cherche la correspondance dans la BIBLIOTHÈQUE fournie (par libellé/code). Correspondance sûre -> prestation_id + confiance "haute". Plusieurs candidats plausibles -> prestation_id null + jusqu'à 3 "candidats" [{prestation_id, libelle}] + confiance "moyenne". Aucune -> prestation_id null + désignation libre propre + confiance "basse".`,
  `3. Décompose les demandes globales en sous-tâches métier. Exemple : "carrelage salle de bain 12 m2" -> dépose de l'existant, préparation/ragréage, fourniture, pose, joints. Une ligne par tâche ; quantités déduites de la consigne (surface dictée -> lignes surfaciques).`,
  `4. Unités autorisées : Fft (forfait), U, pce, m2, ml, h. "forfait" -> Fft, quantité 1.`,
  `5. "en option"/"si le client veut" -> est_option=true. Intitulés de zones ("salle de bain") -> lignes {"type":"titre","designation":...}.`,
  `6. Mode ÉDITION : tu reçois le devis courant (lignes + ids). Tu renvoies UNIQUEMENT des opérations sur ces ids — jamais le devis complet. Formats : {"op":"ajouter_ligne","position":"fin"|{"apres_ligne_id":id},"ligne":{...}} ; {"op":"modifier_ligne","ligne_id":id,"champs":{quantite?,designation?,unite?,est_option?,prix_unitaire? (seulement si prix dicté)}} ; {"op":"supprimer_ligne","ligne_id":id}. Ambigu (plusieurs lignes) -> {"op":"ambigu","message":...,"candidats_ligne_ids":[...],"operation_en_attente":{...}} — ne tranche pas.`,
  `7. Langue : français. Désignations professionnelles, concises, sans fautes.`,
  `8. Réponds STRICTEMENT en JSON, sans markdown ni texte autour. Mode creation : {"lignes":[{"type":"titre","designation":...} | {"type":"prestation","prestation_id":id|null,"designation":...,"unite":...,"quantite":n,"est_option":bool,"confiance":"haute"|"moyenne"|"basse","candidats":[]}],"avertissements":[]}. Mode edition : {"operations":[...],"avertissements":[]}.`
].join('\n');
let user = `MODE: ${p.mode}\nENTITÉ: ${p.contexte.entite_code}\nCLIENT: ${p.contexte.client.nom} (catégorie ${p.contexte.client.categorie_tarifaire || 'inconnue'})\nBIBLIOTHÈQUE (id | code | libellé | unité):\n${biblioTxt}\n`;
if (p.mode === 'edition') {
  const lignes = p.contexte.devis_courant.lignes.map(l => `${l.id} | ${l.designation} | ${l.unite || ''} | ${l.quantite ?? ''} | ${l.est_titre ? 'TITRE' : ''}${l.est_option ? 'OPTION' : ''}`).join('\n');
  user += `DEVIS COURANT (id | désignation | unité | qté | drapeaux):\n${lignes}\n`;
}
user += `CONSIGNE:\n${ctx.consigne}`;
return [{ json: { system, user, biblioIds: biblioItems.map(b => b.id), payload: p, transcription: ctx.transcription } }];

const prep = $('6. Construction prompt').first().json;
const res = $input.first().json || {};

const UNITES = ['Fft','U','pce','m2','ml','h'];
const normUnite = (u) => {
  if (!u) return 'Fft';
  if (UNITES.includes(u)) return u;
  const m = String(u).toLowerCase().replace('²','2').trim();
  const map = { 'm2':'m2','ml':'ml','h':'h','heure':'h','heures':'h','u':'U','unite':'U','unité':'U','pce':'pce','piece':'pce','pièce':'pce','pieces':'pce','pièces':'pce','fft':'Fft','forfait':'Fft' };
  return map[m] || 'Fft';
};

const out = { ok: true, mode: prep.payload.mode, transcription: prep.transcription || null, avertissements: [] };

// Récupère le contenu LLM quel que soit le format renvoyé par le nœud OpenAI natif
let content = (res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content)
  || (res && res.message && res.message.content)
  || res.content || res.text || null;

let raw;
if (content && typeof content === 'object') {
  raw = content;
} else if (typeof content === 'string') {
  try { raw = JSON.parse(content.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim()); }
  catch (e) { return [{ json: { ok: false, erreur: 'llm_indisponible' } }]; }
} else if (res && (Array.isArray(res.lignes) || Array.isArray(res.operations))) {
  raw = res;
} else {
  return [{ json: { ok: false, erreur: 'llm_indisponible' } }];
}

const ids = new Set(prep.biblioIds);
const cleanLigne = (l) => {
  if (!l || typeof l !== 'object') return null;
  if (l.type === 'titre') return { type: 'titre', designation: String(l.designation || '').slice(0, 300) };
  const ligne = { type: 'prestation', designation: String(l.designation || '').slice(0, 300) };
  if (!ligne.designation) return null;
  if (l.prestation_id && ids.has(l.prestation_id)) ligne.prestation_id = l.prestation_id;
  else { if (l.prestation_id) out.avertissements.push(`Référence bibliothèque inconnue ignorée pour « ${ligne.designation} »`); ligne.prestation_id = null; }
  ligne.unite = normUnite(l.unite);
  let q = Number(l.quantite);
  if (!isFinite(q) || q <= 0) { q = 1; out.avertissements.push(`Quantité invalide remplacée par 1 pour « ${ligne.designation} »`); }
  ligne.quantite = q;
  ligne.est_option = !!l.est_option;
  ligne.confiance = ['haute','moyenne','basse'].includes(l.confiance) ? l.confiance : (ligne.prestation_id ? 'moyenne' : 'basse');
  ligne.candidats = Array.isArray(l.candidats) ? l.candidats.filter(c => c && ids.has(c.prestation_id)).map(c => ({ prestation_id: c.prestation_id, libelle: String(c.libelle || '') })).slice(0, 3) : [];
  return ligne;
};

if (prep.payload.mode === 'creation') {
  const lignes = Array.isArray(raw.lignes) ? raw.lignes.map(cleanLigne).filter(Boolean) : [];
  if (!lignes.length) return [{ json: { ok: false, erreur: 'llm_indisponible' } }];
  out.lignes = lignes;
} else {
  const ligneIds = new Set((prep.payload.contexte.devis_courant?.lignes || []).map(l => l.id));
  const ops = Array.isArray(raw.operations) ? raw.operations : [];
  out.operations = [];
  for (const o of ops) {
    if (!o || typeof o !== 'object') continue;
    if (o.op === 'ajouter_ligne' && o.ligne) {
      const ligne = cleanLigne(o.ligne);
      if (!ligne) continue;
      const position = (o.position && o.position.apres_ligne_id && ligneIds.has(o.position.apres_ligne_id)) ? o.position : 'fin';
      out.operations.push({ op: 'ajouter_ligne', position, ligne });
    } else if (o.op === 'modifier_ligne' && ligneIds.has(o.ligne_id) && o.champs && typeof o.champs === 'object') {
      const champs = {};
      if (o.champs.quantite !== undefined) { const q = Number(o.champs.quantite); if (isFinite(q) && q > 0) champs.quantite = q; }
      if (o.champs.designation) champs.designation = String(o.champs.designation).slice(0, 300);
      if (o.champs.unite) champs.unite = normUnite(o.champs.unite);
      if (o.champs.est_option !== undefined) champs.est_option = !!o.champs.est_option;
      if (o.champs.prix_unitaire !== undefined) { const px = Number(o.champs.prix_unitaire); if (isFinite(px) && px >= 0) champs.prix_unitaire = px; }
      if (Object.keys(champs).length) out.operations.push({ op: 'modifier_ligne', ligne_id: o.ligne_id, champs });
      else out.avertissements.push('Modification sans champ valide ignorée');
    } else if (o.op === 'supprimer_ligne' && ligneIds.has(o.ligne_id)) {
      out.operations.push({ op: 'supprimer_ligne', ligne_id: o.ligne_id });
    } else if (o.op === 'ambigu') {
      const cands = (Array.isArray(o.candidats_ligne_ids) ? o.candidats_ligne_ids : []).filter(id => ligneIds.has(id));
      if (cands.length >= 2) out.operations.push({ op: 'ambigu', message: String(o.message || 'Précision nécessaire'), candidats_ligne_ids: cands, operation_en_attente: (o.operation_en_attente && typeof o.operation_en_attente === 'object') ? o.operation_en_attente : null });
    } else {
      out.avertissements.push('Opération invalide ignorée');
    }
  }
  if (!out.operations.length) return [{ json: { ok: false, erreur: 'aucune_operation', avertissements: out.avertissements } }];
}
if (Array.isArray(raw.avertissements)) out.avertissements.push(...raw.avertissements.map(a => String(a)).slice(0, 10));
return [{ json: out }];
